def solve_n3():
    solutions = []
    for a in range(1, 20):
        for b in range(a + 1, 40):
            # (a+b+c)(ab+bc+ca+1) = 12abc
            # (a+b+c)(ab+1 + c(a+b)) = 12abc
            # (a+b)(ab+1) + c(a+b)^2 + c(ab+1) + c^2(a+b) = 12abc
            # (a+b)c^2 + c(a^2+2ab+b^2+ab+1-12ab) + (a+b)(ab+1) = 0
            # (a+b)c^2 + c(a^2-9ab+b^2+1) + (a+b)(ab+1) = 0
            A = a + b
            B = a**2 - 9*a*b + b**2 + 1
            C = (a+b)*(a*b+1)

            # Solve Ac^2 + Bc + C = 0
            # c = (-B \pm sqrt(B^2 - 4AC)) / (2A)
            discriminant = B**2 - 4*A*C
            if discriminant >= 0:
                sqrt_d = int(discriminant**0.5)
                if sqrt_d**2 == discriminant:
                    for sign in [-1, 1]:
                        c = (-B + sign * sqrt_d) / (2 * A)
                        if c.is_integer() and c > b:
                            solutions.append((a, b, int(c)))
    return sorted(list(set(solutions)))

