    for n in range(1, n_max):
        for a in range(1, 20):
            for b in range(a + 1, 40):
                for c in range(b + 1, 60):
                    num = (a+b+c)*(a*b+b*c+c*a+1)
                    den = 4*a*b*c
                    if num == n*den:
                        # Found a solution (a, b, c)
                        # Check if it can be extended
                        # Quadratic for a: a^2(b+c) + a(b^2+c^2+bc+1-4nbc) + (b^2c+bc^2+b+c) = 0
