                        if is_perfect_square(Da):
                            print(f"n={n} has a solution {a,b,c} with Da a square")

                        # Quadratic for b: b^2(a+c) + b(a^2+c^2+ac+1-4nac) + (a^2c+ac^2+a+c) = 0
                        Db = (a**2 + c**2 + a*c + 1 - 4*n*a*c)**2 - 4*(a+c)*(a**2*c + a*c**2 + a + c)
