                            print(f"n={n} has a solution {a,b,c} with Db a square")

                        # Quadratic for c: c^2(a+b) + c(a^2+b^2+ab+1-4nab) + (a^2b+ab^2+a+b) = 0
                        Dc = (a**2 + b**2 + a*b + 1 - 4*n*a*b)**2 - 4*(a+b)*(a**2*b + a*b**2 + a + b)
                        if is_perfect_square(Dc):
                            print(f"n={n} has a solution {a,b,c} with Dc a square")

